224	  let upper;
225	  if (v1 === 0 && v2 === 0) {
226	    lower = diff;
227	    upper = diff;
228	  } else {
229	    const s1 = v1 / n1;
230	    const s2 = v2 / n2;
231	    const standardError = Math.sqrt(s1 + s2);
