233	    const margin = tCriticalValue(df, alpha) * standardError;
234	    lower = diff - margin;
235	    upper = diff + margin;
236	  }
237	
238	  return {
239	    level: 1 - alpha,
240	    lower_ns: lower,
241	    upper_ns: upper,
242	    lower_percent: m1 === 0 ? null : (lower / m1) * 100,
243	    upper_percent: m1 === 0 ? null : (upper / m1) * 100,
244	  };
245	}
246	
247	module.exports = {
248	  computeSummary,
249	  round6,
250	  welchTest,
251	  tCriticalValue,
252	  welchMeanInterval,
253	};
