1	'use strict';
2	
3	const { spawn } = require('node:child_process');
4	const fs = require('node:fs/promises');
5	const { computeSummary } = require('./stats');
6	
7	const EXIT_OK = 0;
8	const EXIT_USAGE = 2;
9	const EXIT_MEASURE_ERROR = 3;
10	const EXIT_OUTPUT_ERROR = 4;
11	
12	const KNOWN_KEYS = new Set(['command', 'runs', 'warmup', 'timeout-ms', 'output']);
13	
14	// 解析 --key value / --key=value 形式的参数。
15	// knownKeys 为允许的参数名集合，缺省为 collect 的参数集。
16	// 返回 { values, error }；无法解析时 error 为说明字符串。
17	function parseArgs(tokens, knownKeys = KNOWN_KEYS) {
18	  const values = {};
19	  for (let i = 0; i < tokens.length; i++) {
20	    const token = tokens[i];
21	    if (!token.startsWith('--')) {
22	      return { values, error: `无法解析的参数: ${token}` };
23	    }
24	    const body = token.slice(2);
25	    const eq = body.indexOf('=');
26	    let key;
27	    let value;
28	    if (eq >= 0) {
29	      key = body.slice(0, eq);
30	      value = body.slice(eq + 1);
31	    } else {
32	      key = body;
33	      if (i + 1 >= tokens.length) {
34	        return { values, error: `参数 --${key} 缺少取值` };
35	      }
36	      value = tokens[++i];
37	    }
38	    if (!key) {
39	      return { values, error: `无法解析的参数: ${token}` };
40	    }
41	    if (!knownKeys.has(key)) {
42	      return { values, error: `未知参数: --${key}` };
43	    }
44	    if (Object.prototype.hasOwnProperty.call(values, key)) {
45	      return { values, error: `参数 --${key} 重复指定` };
46	    }
47	    values[key] = value;
48	  }
49	  return { values, error: null };
50	}
51	
52	function parsePositiveIntOption(values, key, { min, required }) {
53	  if (!Object.prototype.hasOwnProperty.call(values, key)) {
54	    if (required) return { error: `缺少必填参数 --${key}` };
55	    return { value: undefined };
56	  }
57	  const raw = values[key];
58	  // 仅接受十进制整数写法
59	  if (!/^-?\d+$/.test(raw)) {
60	    return { error: `参数 --${key} 必须为整数，实际为: ${raw}` };
61	  }
62	  const value = Number(raw);
63	  if (!Number.isSafeInteger(value) || value < min) {
64	    return { error: `参数 --${key} 必须为 >= ${min} 的整数，实际为: ${raw}` };
65	  }
66	  return { value };
67	}
68	
69	// 顺序执行一次目标命令。
70	// 返回 { startedAt, durationNs, exitCode, reason }
71	// reason 为 null 表示正常退出（exitCode 可能非零，由调用方按阶段处理），
72	// 或为 'timeout'；进程无法启动时抛错（error.code 通常为 ENOENT/EAGAIN）。
73	function runOnce(command, timeoutMs) {
74	  return new Promise((resolve, reject) => {
75	    let child;
76	    try {
77	      child = spawn(command, {
78	        shell: true,
79	        stdio: ['ignore', 'pipe', 'pipe'],
80	        // 非 Windows 下使子 shell 成为新进程组组长，超时可整组清理，避免遗留孙进程。
81	        detached: process.platform !== 'win32',
82	      });
83	    } catch (err) {
84	      reject(err);
85	      return;
86	    }
87	
88	    // 丢弃被测命令输出，保持本工具 stdout/stderr 干净，同时排空管道避免反压。
89	    child.stdout?.on('data', () => {});
90	    child.stderr?.on('data', () => {});
91	
92	    const startedAt = new Date();
93	    const startHr = process.hrtime.bigint();
94	    let settled = false;
95	    let timedOut = false;
96	
97	    const timer = setTimeout(() => {
98	      timedOut = true;
99	      try {
100	        if (child.pid && process.platform !== 'win32') {
101	          try {
102	            process.kill(-child.pid, 'SIGKILL');
103	          } catch {
104	            child.kill('SIGKILL');
105	          }
106	        } else {
107	          child.kill('SIGKILL');
108	        }
109	      } catch {
110	        // 进程可能已退出
111	      }
112	    }, timeoutMs);
113	    timer.unref?.();
114	
115	    child.on('error', (err) => {
116	      if (settled) return;
117	      settled = true;
118	      clearTimeout(timer);
119	      reject(err);
120	    });
121	
122	    child.on('close', (code, signal) => {
123	      if (settled) return;
124	      settled = true;
125	      clearTimeout(timer);
126	      const durationNs = Number(process.hrtime.bigint() - startHr);
127	      if (timedOut) {
128	        resolve({ startedAt, durationNs, exitCode: null, reason: 'timeout' });
129	        return;
130	      }
131	      // 被信号终止（非本工具超时）同样记为 nonzero_exit，exit_code 以 null 表示无可用退出码。
132	      resolve({ startedAt, durationNs, exitCode: code, signal, reason: null });
133	    });
134	  });
135	}
136	
137	function emptySummary() {
138	  return {
139	    count: 0,
