  assert.equal(r6(ci.lower_percent), r6((2 - 4.302653) / 10 * 100));
  assert.equal(r6(ci.upper_percent), r6((2 + 4.302653) / 10 * 100));
  assert.ok(Math.abs((ci.lower_ns + ci.upper_ns) / 2 - 2) < 1e-9);
});

